    if (~rst_n) begin
        stage1_out <= 4'b0000;
        stage2_out <= 4'b0000;
        out <= 4'b0000;
    end else if (en) begin
        stage1_out <= ~in + 4'b0001;
        stage2_out <= stage1_out;
        out <= stage2_out;
    end
end

endmodule

