module up_down_counter3bit(
	input clk,
	input rst,
	input up_down,
	output reg [2:0] count);

	always @(posedge clk or posedge rst) begin
		if (rst)
			count <= 3'b0;
		else if (up_down)
			count <= count + 1;
		else
			count <= count - 1;
	end

endmodule

